557	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
558	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
559	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
560	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
561	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
562	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
563	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
564	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
565		handoverID = clean(handoverID)
566		itemID = clean(itemID)
567		operator = clean(operator)
568		reason = clean(reason)
569		trackingNote = clean(trackingNote)
570		nextFollowOwner = clean(nextFollowOwner)
571	
572		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
573			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
574		}
575		if err := requireNonEmpty("操作人", operator); err != nil {
576			return Handover{}, err
577		}
578	
579		var result Handover
580		err := svc.store.mutate(func(d *Data) error {
581			h, _ := findHandover(d, handoverID)
582			if h == nil {
583				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
584			}
585			e, _ := findEntry(h, itemID)
586			if e == nil {
587				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
588			}
589			if e.Status.Received() {
590				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
591					ErrHandoverState, e.ItemID, e.Status.Label())
592			}
593			if e.Status == EntryReturned {
594				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
595				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
596				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
597				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
598					ErrHandoverState, e.ItemID, h.ID)
599			}
600			switch action {
601			case ActionReturn:
602				if err := requireNonEmpty("退回原因", reason); err != nil {
603					return err
604				}
605			case ActionTrack:
606				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
607					return err
608				}
609				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
610					return err
611				}
612			}
613	
614			now := svc.now()
615			switch action {
616			case ActionConfirm:
617				e.Status = EntryConfirmed
618			case ActionTrack:
619				e.Status = EntryTracking
620				e.TrackingNote = trackingNote
621				e.FollowOwner = nextFollowOwner
622			case ActionReturn:
623				e.Status = EntryReturned
624				e.Rounds = append(e.Rounds, ReturnRound{
625					Seq:            len(e.Rounds) + 1,
626					ReturnedAt:     now,
627					ReturnOperator: operator,
628					Reason:         reason,
629				})
630			}
631			e.Operator = operator
632			e.ProcessedAt = &now
633	
634			if action != ActionReturn {
635				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
636				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
637					it.CurrentShiftID = h.ToShiftID
638					if !contains(it.ShiftIDs, h.ToShiftID) {
639						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
640					}
641					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
642					if action == ActionTrack {
643						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
644						it.FollowOwner = nextFollowOwner
645					}
646					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
647				}
648			}
649	
650			if h.Completed() {
651				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
652				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
653				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
654				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
655				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
656				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
657				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
658				// 项无法再处理，完成时间不会被改写。
659				h.CompletedAt = &now
660			}
661			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
662			// 与完成时间）不与系统保存的交接共享内存。
663			result = cloneHandover(*h)
664			return nil
665		})
666		return result, err
667	}
668	
669	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
670	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
671	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
672	
673	func contains(xs []string, x string) bool {
674		for _, v := range xs {
675			if v == x {
676				return true
677			}
678		}
679		return false
680	}
681	
682	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
683	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
684	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
685	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
686	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
687	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
688	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
689		handoverID = clean(handoverID)
690		itemID = clean(itemID)
691		operator = clean(operator)
692		supplement = clean(supplement)
693		if err := requireNonEmpty("操作人", operator); err != nil {
694			return Handover{}, err
695		}
696		if err := requireNonEmpty("补充说明", supplement); err != nil {
697			return Handover{}, err
698		}
699	
700		var result Handover
701		err := svc.store.mutate(func(d *Data) error {
702			h, _ := findHandover(d, handoverID)
703			if h == nil {
704				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
705			}
706			e, _ := findEntry(h, itemID)
707			if e == nil {
708				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
709			}
710			if e.Status != EntryReturned {
711				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
712					ErrHandoverState, e.ItemID, e.Status.Label())
713			}
714			if len(e.Rounds) == 0 {
715				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
716			}
717			round := &e.Rounds[len(e.Rounds)-1]
718			if round.ResubmittedAt != nil {
719				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
720			}
721			now := svc.now()
722			round.Supplement = supplement
723			round.SupplementOperator = operator
724			round.SupplementAt = &now
725			round.ResubmittedAt = &now
726			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
727			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
728			e.Status = EntryPending
729			e.Operator = ""
730			e.ProcessedAt = nil
731			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
732			result = cloneHandover(*h)
733			return nil
734		})
735		return result, err
736	}
