766	
767	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
768	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
769	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
770	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
771	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
772	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
773	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
774	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
775	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
776	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
777	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
778	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
779	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
780	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
781	// 不改变事项、交接进度或班次结束时记录。
782	// 返回的整份结果是查询当时的独立副本，与班次报告同一约定：事项最新信息
783	// （含流经班次、历史事件与关闭时间）、处理经过（含各轮退回原因、补充说明与
784	// 补充时间）和各次交接当前结果（含处理时间与历次退回/补充记录）全部深拷贝，
785	// 处理经过与交接当前结果中同一次补充的时间也各是一份副本。调用方改动结果
786	// 不影响系统保存的数据与其他已取得的结果，系统随后的正常处理（补充后重新
787	// 提交、接收、修改、关闭等）也不会改写这份结果；再次查询才反映最新内容。
788	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
789		itemID = clean(itemID)
790		d := &svc.store.data
791		it, _ := findItem(d, itemID)
792		if it == nil {
793			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
794		}
795		j := ItemJourney{Item: cloneItem(*it)}
796	
797		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
798		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
799		// 该轮重新提交、后续处理）。
800		type keyedEvent struct {
801			ev    JourneyEvent
802			group string // "" 表示事项自身事件，否则为交接编号
803			ord   int    // 同一（时刻、分组）内的先后
804		}
805		var events []keyedEvent
806		seq := 0
807		add := func(ev JourneyEvent, group string) {
808			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
809			seq++
810		}
811	
812		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
813		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
814		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
815		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
816		merge := newReceivedMerge(it.Events)
817	
818		hs := append([]Handover(nil), d.Handovers...)
819		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
820		for k := range hs {
821			h := &hs[k]
822			e, _ := findEntry(h, itemID)
823			if e == nil {
824				continue
825			}
826			j.HasHandovers = true
827			j.Results = append(j.Results, EntryView{
828				HandoverID: h.ID,
829				FromShift:  h.FromShiftID,
830				ToShift:    h.ToShiftID,
831				Entry:      cloneEntry(*e),
832			})
833	
834			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
835			add(JourneyEvent{
836				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
837				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
838			}, h.ID)
839			for _, r := range e.Rounds {
840				add(JourneyEvent{
841					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
842					Kind: "return", Operator: r.ReturnOperator,
843					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
844					RoundSeq: r.Seq, Reason: r.Reason,
845				}, h.ID)
846				if r.ResubmittedAt != nil {
847					add(JourneyEvent{
848						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
849						Kind: "resubmit", Operator: r.SupplementOperator,
850						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
851						RoundSeq: r.Seq, Supplement: r.Supplement,
852						// 补充时间复制一份：处理经过与交接当前结果中同一次补充
853						// 各属各的副本，改动其中一处不影响另一处与存储记录。
854						SupplementOperator: r.SupplementOperator, SupplementAt: cloneTimePtr(r.SupplementAt),
855					}, h.ID)
856				}
857			}
858			if e.Status == EntryReturned && len(e.Rounds) == 0 {
859				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
860				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
861				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
862				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
863				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
864				ev := JourneyEvent{
865					Kind: "return-incomplete", Operator: e.Operator,
866					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
867					HistoryIncomplete: true,
868				}
869				if validProcessedAt(e.ProcessedAt) {
870					ev.At, ev.TimeKnown = *e.ProcessedAt, true
871				}
872				add(ev, h.ID)
873			}
874			if e.Status.Received() {
875				rcpt := receiptFromEntry(h, e)
876				ev := JourneyEvent{
877					Kind: rcpt.kind, Operator: e.Operator,
878					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
879					TrackingNote: e.TrackingNote,
880					// 继续跟踪当时指定的后续负责人取自交接记录快照，
881					// 之后修改事项负责人不改变这里的历史值。
882					FollowOwner: e.FollowOwner,
883				}
884				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
885				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
886				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
887				if rcpt.timeKnown {
888					ev.At, ev.TimeKnown = rcpt.at, true
889				}
890				add(ev, h.ID)
891				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
892				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
893				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
894				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
895				merge.consider(rcpt)
896			}
897		}
898	
899		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
900		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
901		for i, iev := range it.Events {
902			if iev.Kind == "received" && merge.isUsed(i) {
903				continue
904			}
905			add(JourneyEvent{
906				At: iev.At, TimeKnown: !iev.At.IsZero(),
907				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
908			}, "")
909		}
910	
911		sort.SliceStable(events, func(i, k int) bool {
912			a, b := events[i], events[k]
913			if a.ev.TimeKnown != b.ev.TimeKnown {
914				return a.ev.TimeKnown
915			}
916			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
917				return a.ev.At.Before(b.ev.At)
918			}
919			if a.group != b.group {
920				return a.group < b.group
921			}
922			return a.ord < b.ord
923		})
924		for _, ke := range events {
925			j.Events = append(j.Events, ke.ev)
926		}
927		return j, nil
928	}
929	
930	// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
931	// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
932	func (svc *Service) GetHandover(id string) (Handover, error) {
933		h, _ := findHandover(&svc.store.data, clean(id))
934		if h == nil {
935			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
936		}
937		return cloneHandover(*h), nil
938	}
939	
940	// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
941	func (svc *Service) ListHandovers() []Handover {
942		out := make([]Handover, len(svc.store.data.Handovers))
943		for i, h := range svc.store.data.Handovers {
944			out[i] = cloneHandover(h)
945		}
946		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
947		return out
948	}
949	
950	// OverlapNotes 返回涉及指定班次的全部重叠说明。
951	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
952		shiftID = clean(shiftID)
953		out := []OverlapNote{}
954		for _, n := range svc.store.data.Notes {
955			if n.ShiftA == shiftID || n.ShiftB == shiftID {
956				out = append(out, n)
957			}
958		}
959		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
960		return out
961	}
962	
963	// cloneTimePtr 复制时间指针，nil 保持 nil。
964	func cloneTimePtr(t *time.Time) *time.Time {
965		if t == nil {
966			return nil
967		}
968		v := *t
969		return &v
970	}
971	
972	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
973	func cloneItem(it Item) Item {
974		out := it
975		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
976		out.Events = append([]ItemEvent(nil), it.Events...)
977		out.ClosedAt = cloneTimePtr(it.ClosedAt)
978		return out
979	}
980	
981	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
982	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
983		out := s
984		out.ClosedAt = cloneTimePtr(s.ClosedAt)
985		return out
986	}
987	
988	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
989	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
990	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
991		if rec == nil {
992			return nil
993		}
994		out := &ShiftCloseRecord{}
995		if rec.Items != nil {
996			out.Items = make([]CloseItemSnapshot, len(rec.Items))
997			for i, s := range rec.Items {
998				out.Items[i] = cloneCloseItemSnapshot(s)
999			}
1000		}
1001		return out
1002	}
1003	
1004	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
1005	func cloneShift(sh Shift) Shift {
1006		out := sh
1007		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
1008		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
1009		return out
1010	}
1011	
1012	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
1013	func cloneEntry(e HandoverEntry) HandoverEntry {
1014		out := e
1015		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
1016		if e.Rounds != nil {
1017			out.Rounds = make([]ReturnRound, len(e.Rounds))
1018			for i, r := range e.Rounds {
1019				out.Rounds[i] = r
1020				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
1021				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
1022			}
1023		}
1024		return out
1025	}
1026	
1027	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
1028	func cloneHandover(h Handover) Handover {
1029		out := h
1030		out.CompletedAt = cloneTimePtr(h.CompletedAt)
1031		if h.Entries != nil {
1032			out.Entries = make([]HandoverEntry, len(h.Entries))
1033			for i, e := range h.Entries {
1034				out.Entries[i] = cloneEntry(e)
1035			}
1036		}
1037		return out
1038	}
1039	
1040	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1041	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1042	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1043	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
1044	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
1045	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
1046	// 也不会改写这份报告；再次查询才反映最新内容。
1047	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1048		shiftID = clean(shiftID)
1049		d := &svc.store.data
1050		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1051		sh, _ := findShift(d, shiftID)
1052		if sh == nil {
1053			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1054		}
1055		rep.Shift = cloneShift(*sh)
1056	
1057		for _, n := range d.Notes {
1058			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1059				rep.OverlapNotes = append(rep.OverlapNotes, n)
1060			}
1061		}
1062		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1063	
1064		switch {
1065		case !sh.Closed:
1066			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1067			rep.Items = currentItemsOfShift(d, sh.ID)
1068		case sh.CloseRecord != nil:
1069			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1070			rep.ItemsAtClose = true
1071			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
1072			for i, s := range sh.CloseRecord.Items {
1073				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
1074			}
1075			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1076			for _, s := range rep.CloseItems {
1077				if it, _ := findItem(d, s.ItemID); it != nil {
1078					rep.LatestItems[s.ItemID] = cloneItem(*it)
1079				}
1080			}
1081		default:
1082			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1083			rep.HistoryIncomplete = true
1084			rep.Items = currentItemsOfShift(d, sh.ID)
1085		}
1086		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1087		for i := range rep.Items {
1088			rep.Items[i] = cloneItem(rep.Items[i])
1089		}
1090	
1091		for i := range d.Handovers {
1092			h := &d.Handovers[i]
1093			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1094			if !involved {
1095				continue
1096			}
1097			if h.FromShiftID == sh.ID {
1098				cp := cloneHandover(*h)
1099				rep.Outgoing = &cp
1100			}
1101			if h.ToShiftID == sh.ID {
1102				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
1103			}
1104			for j := range h.Entries {
1105				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1106					HandoverID: h.ID,
1107					FromShift:  h.FromShiftID,
1108					ToShift:    h.ToShiftID,
1109					Entry:      cloneEntry(h.Entries[j]),
1110				})
1111			}
1112		}
1113		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1114		for k := range rep.Results {
1115			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1116		}
1117		return rep, nil
1118	}
1119

