146		if round.SupplementAt == nil || round.ResubmittedAt == nil {
147			t.Fatalf("前置：当前结果的退回轮次应记录补充时间与重新提交时间")
148		}
149		origEvent, origResult := *res.SupplementAt, *round.SupplementAt
150		if !origEvent.Equal(origResult) {
151			t.Fatalf("前置：两处展示同一次补充，时间应一致：%v vs %v", origEvent, origResult)
152		}
153	
154		// 改当前结果里的补充时间，处理经过中的同一补充保留原值。
155		*round.SupplementAt = forge
156		if !res.SupplementAt.Equal(origEvent) {
157			t.Fatalf("改动当前结果的补充时间不应连带改掉处理经过：%v", res.SupplementAt)
